using StackExchange.Redis;

static async Task TransferAsync(
    IDatabase db, string from, string to, long points)
{
    var tx = db.CreateTransaction(); // MULTI ... EXEC
    var debit = tx.StringDecrementAsync(from, points);
    var credit = tx.StringIncrementAsync(to, points);
    if (!await tx.ExecuteAsync()) return; // Test: returned true
    await Task.WhenAll(debit, credit); // Test: the debit threw
    // "ERR value is not an integer or out of range" for "250.5",
    // yet the credit was applied: Karim 40 -> 140, Mona unchanged
}

using StackExchange.Redis;

static async Task<bool> TransferAsync(
    IDatabase db, string from, string to, long points)
{
    // Check everything before the first write: a script can't roll back
    const string script = """
        local a = tonumber(redis.call('GET', KEYS[1]))
        local b = tonumber(redis.call('GET', KEYS[2]) or '0')
        local n = tonumber(ARGV[1])
        if not a or not b or a % 1 ~= 0 or b % 1 ~= 0 or a < n then
          return 0
        end
        redis.call('DECRBY', KEYS[1], n)
        redis.call('INCRBY', KEYS[2], n)
        return 1
        """;
    var result = await db.ScriptEvaluateAsync(script, [from, to], [points]);
    return (int)result == 1; // Test: false for "250.5", nothing written
}
